using System;using System.IO;using System.Collections.Generic;using System.Xml.Linq;class Origin{public string CreationId;}class ShellRecord{public CloneSlice Progression;public Origin Origin;}static class RepoSlices{public static void CheckWrite(ShellRecord record){        if(!RebirthStationRecipeDiscoveryPersistence.MatchesCreation(record.Progression.RecipeDiscoveries.Values,record.Origin.CreationId))throw new InvalidDataException("Recipe discovery character mismatch");}public static bool CheckRead(CloneSlice progression,Origin origin,out string error){error=null;            if(!RebirthStationRecipeDiscoveryPersistence.MatchesCreation(progression.RecipeDiscoveries.Values,origin.CreationId)){error="Recipe discovery character mismatch";return false;}return true;}public static XElement Write(CloneSlice state,string ownerKey){var node=new XElement("progression");        node.Add(RebirthStationRecipeDiscoveryPersistence.Write(state.RecipeDiscoveries,ownerKey));return node;}public static bool Read(XElement node,string ownerKey,out CloneSlice state,out string error){state=new CloneSlice();        Dictionary<string,RebirthStationRecipeDiscoveryRecord> discoveries;
        if(!RebirthStationRecipeDiscoveryPersistence.TryRead(node,ownerKey,out discoveries,out error))return false;
        foreach(var pair in discoveries)state.RecipeDiscoveries.Add(pair.Key,pair.Value);
return true;}}